function getPositionLeverage(Market storage self, address account, uint256 subaccount, uint256 maxOpenLeverage) internal view returns (uint256 leverage) {
    leverage = self.position[account][subaccount].leverage;

    if (leverage == 0) leverage = 1e18; // default leverage

    // Enforce max leverage limit
    require(leverage <= maxOpenLeverage, "Leverage exceeds max limit");
}

